#include <gtest/gtest.h>
#include <yoga/Yoga.h>
#include "../util/TestUtil.h"

TEST(YogaTest, grid_fr_span_2_proportion_with_non_spanned_track) {
  YGConfigRef config = YGConfigNew();

  YGNodeRef root = YGNodeNewWithConfig(config);
  YGNodeStyleSetPositionType(root, YGPositionTypeAbsolute);
  YGNodeStyleSetWidthMaxContent(root);

  YGNodeRef root_child0 = YGNodeNewWithConfig(config);
  YGNodeStyleSetDisplay(root_child0, YGDisplayGrid);
  YGNodeStyleSetGridTemplateColumnsCount(root_child0, 3);
  YGNodeStyleSetGridTemplateColumn(root_child0, 0, YGGridTrackTypeFr, 1);
  YGNodeStyleSetGridTemplateColumn(root_child0, 1, YGGridTrackTypeFr, 2);
  YGNodeStyleSetGridTemplateColumn(root_child0, 2, YGGridTrackTypeFr, 3);
  YGNodeStyleSetGridTemplateRowsCount(root_child0, 2);
  YGNodeStyleSetGridTemplateRow(root_child0, 0, YGGridTrackTypePoints, 40);
  YGNodeStyleSetGridTemplateRow(root_child0, 1, YGGridTrackTypePoints, 40);
  YGNodeInsertChild(root, root_child0, 0);

  YGNodeRef root_child0_child0 = YGNodeNewWithConfig(config);
  YGNodeStyleSetWidth(root_child0_child0, 60);
  YGNodeStyleSetGridColumnStartSpan(root_child0_child0, 2);
  YGNodeInsertChild(root_child0, root_child0_child0, 0);

  YGNodeRef root_child0_child1 = YGNodeNewWithConfig(config);
  YGNodeInsertChild(root_child0, root_child0_child1, 1);

  YGNodeRef root_child0_child2 = YGNodeNewWithConfig(config);
  YGNodeInsertChild(root_child0, root_child0_child2, 2);

  YGNodeRef root_child0_child3 = YGNodeNewWithConfig(config);
  YGNodeInsertChild(root_child0, root_child0_child3, 3);

  YGNodeRef root_child0_child4 = YGNodeNewWithConfig(config);
  YGNodeInsertChild(root_child0, root_child0_child4, 4);
  YGNodeCalculateLayout(root, YGUndefined, YGUndefined, YGDirectionLTR);

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root));
  ASSERT_FLOAT_EQ(120, YGNodeLayoutGetWidth(root));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0));
  ASSERT_FLOAT_EQ(120, YGNodeLayoutGetWidth(root_child0));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root_child0));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0_child0));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0_child0));
  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetWidth(root_child0_child0));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child0));

  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetLeft(root_child0_child1));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0_child1));
  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetWidth(root_child0_child1));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child1));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0_child2));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child0_child2));
  ASSERT_FLOAT_EQ(20, YGNodeLayoutGetWidth(root_child0_child2));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child2));

  ASSERT_FLOAT_EQ(20, YGNodeLayoutGetLeft(root_child0_child3));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child0_child3));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetWidth(root_child0_child3));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child3));

  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetLeft(root_child0_child4));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child0_child4));
  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetWidth(root_child0_child4));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child4));

  YGNodeCalculateLayout(root, YGUndefined, YGUndefined, YGDirectionRTL);

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root));
  ASSERT_FLOAT_EQ(120, YGNodeLayoutGetWidth(root));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0));
  ASSERT_FLOAT_EQ(120, YGNodeLayoutGetWidth(root_child0));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root_child0));

  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetLeft(root_child0_child0));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0_child0));
  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetWidth(root_child0_child0));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child0));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0_child1));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0_child1));
  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetWidth(root_child0_child1));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child1));

  ASSERT_FLOAT_EQ(100, YGNodeLayoutGetLeft(root_child0_child2));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child0_child2));
  ASSERT_FLOAT_EQ(20, YGNodeLayoutGetWidth(root_child0_child2));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child2));

  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetLeft(root_child0_child3));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child0_child3));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetWidth(root_child0_child3));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child3));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0_child4));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetTop(root_child0_child4));
  ASSERT_FLOAT_EQ(60, YGNodeLayoutGetWidth(root_child0_child4));
  ASSERT_FLOAT_EQ(40, YGNodeLayoutGetHeight(root_child0_child4));

  YGNodeFreeRecursive(root);

  YGConfigFree(config);
}
